def generate():
    lines = []
    lines.append("# Partia Audytowa 19 / 28 (Rekordy 1801 – 1900)\n")
    lines.append("**Zakres:** **Profesora Stefana Myczkowskiego** – **Robotnicza** | [← Powrót do spisu partii (INDEX.md)](INDEX.md)\n")
    lines.append("### Statystyka partii:")
    lines.append("- **Liczba ulic w partii:** 100")
    lines.append("- **Ulice z patronem (postacie):** 18")
    lines.append("- **Ulice toponimiczne i obiektowe:** 82")
    lines.append("- **Portrety CDN Wikimedia Commons:** 15")
    lines.append("- **Źródła archiwalne i monografie:** Klemens Bąkowski (1903), Monografia prof. E. Supranowicz (RCIN PAN), 8 Cyfrowych Aktów Urzędowych (DRK 1880, DRK 1912, Podgórze 1917, DRK 1926/1933, Okupacja 1940/1941, PRL 1951/1955, Rozszerzenie 1973/1975, Dekomunizacja 1991), Biuletyn Informacji Publicznej (BIP RMK), Wikipedia / PWN\n")
    lines.append("---\n")
    lines.append("| Lp. | Ulica w Krakowie | Kategoria | Rok | Patron / Znaczenie dosłowne | Biogram / Rola / Etymologia (PL) | Źródło i odnośnik | Portret | Weryfikacja |")
    lines.append("|:---:|:---|:---|:---:|:---|:---|:---|:---:|:---:|")

    for r in rows:
        lines.append(f"| {r[0]} | {r[1]} | {r[2]} | {r[3]} | {r[4]} | {r[5]} | {r[6]} | {r[7]} | {r[8]} |")

    lines.append("\n## Dziennik Weryfikacji i Zastosowanych Źródeł (Audit Log)")
    for al in audit_log:
        lines.append(f"* **[Lp. {al[0]}] {al[1]}:** {al[2]}")

    lines.append("")

    content = "\n".join(lines)
    with open('docs/audit_batches/batch_19.md', 'w', encoding='utf-8') as f:
        f.write(content)
    print("Zapisano pomyślnie docs/audit_batches/batch_19.md!")

if __name__ == '__main__':
    generate()
